  'Cinq horizons de variation sur un rayon commun. Le milieu du rayon vaut 0 % : un sommet vers l’intérieur est une baisse, vers l’extérieur une hausse. « 1 an » est écarté — il se compte en centaines de pour cent et écraserait les quatre autres.': '五个涨跌周期共用一条半径。半径中点为 0 %：顶点向内表示下跌，向外表示上涨。“1 年”被排除——它动辄数百个百分点，会把其余四个压平。',
