  'Surface : {size}. Couleur : volatilité sur 7 jours — l’écart-type des variations de la courbe publiée par la source. Elle n’a pas de sens de hausse ou de baisse : la rampe va du calme à l’agité, et son sommet est le plus agité des actifs AFFICHÉS. Les couleurs de cette vue classent donc le lot du jour ; elles ne se comparent pas d’un jour à l’autre.': '面积：{size}。颜色：7 日波动率——数据源所公布序列涨跌幅的标准差。它没有涨跌方向：色阶由平静到剧烈，最深一端是当前所显示资产中最剧烈者。因此本视图的配色只对当天这批资产排序，不能跨日比较。',
