  'Cette page couvre les actions tokenisées, seule catégorie d’actifs du monde réel que notre source publie en tant que telle. Les bons du Trésor, l’immobilier et le crédit privé tokenisés existent, mais aucun agrégat gratuit ne les recense — ils ne sont donc pas affichés plutôt que d’être estimés.': '本页涵盖代币化股票，这是我们的数据源唯一以此形式发布的现实世界资产类别。代币化的国债、房地产与私募信贷确实存在，但没有免费的汇总数据收录它们——因此宁可不显示，也不做估算。',
