  /* ── Titres et chapeaux de page ─────────────────────────────────────────── */
  "Données de trading": "交易数据",
  "L’activité du marché crypto en quatre plans : les agrégats mondiaux, la répartition du volume entre les places, l’exposition sur les produits dérivés, puis les mouvements de la période.": "从四个层面看加密市场的活跃度：全球总量、各平台之间的成交量分布、衍生品上的敞口，以及该时段的涨跌。",
  "Points marquants": "重点关注",
  "Ce qui sort de l’ordinaire aujourd’hui : ce qu’on regarde, ce qui bouge, ce qui s’échange, ce qui apparaît.": "今天的异动：大家在看什么、什么在动、什么在成交、什么刚出现。",
  "Comment les chiffres affichés sur ZENKUU sont collectés, vérifiés et présentés — et ce qu’ils ne disent pas.": "ZENKUU 上的数字如何采集、核对与呈现——以及它们没有说的部分。",
  "Classements crypto": "加密货币排行",
  "Quatre palmarès à confronter : ce qui monte, ce qui baisse, ce qui s’échange le plus, et ce qui tourne le plus vite au regard de sa taille.": "四份可相互对照的榜单：上涨的、下跌的、成交最多的，以及相对自身规模周转最快的。",
  "Deux à six actifs côte à côte, toutes classes confondues : trajectoires ramenées à une base commune, puis les chiffres qui les séparent.": "两到六项资产并排比较，不限类别：走势归到同一基准，再看区分它们的数字。",
  "Carte thermique du marché": "市场热力图",
  "Le marché en un coup d’œil : la surface porte la capitalisation, la couleur porte la variation. Basculez entre les pièces et les secteurs, et cliquez un rectangle pour l’ouvrir.": "一眼看懂市场：面积代表市值，颜色代表涨跌。可在币种与板块之间切换，点击方块即可打开。",
  "Dérivés": "衍生品",
  "Les contrats les plus actifs, leur intérêt ouvert et leur taux de financement. Un contrat perpétuel n’a pas d’échéance : son taux de financement est ce qui le raccroche au cours au comptant.": "最活跃的合约、其未平仓量与资金费率。永续合约没有到期日，把它拴住现货价格的正是资金费率。",
  "Les trois cents actifs dont la source a relevé un cours pour la première fois le plus récemment, du plus récent au plus ancien. Ceux que nous suivons par ailleurs portent leur logo et mènent à leur fiche.": "数据源最近首次记录到价格的三百项资产，由新到旧。我们另行跟踪的资产会显示其标识，并可进入详情页。",
  "Paramètres": "设置",
  "Vos réglages d’affichage, votre compte et l’origine des chiffres. ZENKUU n’exécute aucun ordre et ne détient aucun fonds : il n’y a ici ni moyen de paiement, ni limite de transaction, ni vérification d’identité — et rien à payer, le site n’ayant pas d’offre payante.": "你的显示设置、账户以及数据来源。ZENKUU 不执行任何委托，也不托管资金：这里没有支付方式、没有交易限额、没有身份核验——也无需付费，本站没有付费方案。",
  "Les places de contrats perpétuels, classées par l’exposition qu’elles portent réellement — l’intérêt ouvert — et non par le volume qu’elles affichent. ZENKUU ne référence aucun carnet d’ordres et ne permet aucune transaction : ce registre situe l’activité, il n’y donne pas accès.": "永续合约平台按其实际承载的敞口——未平仓量——排序，而非按其公布的成交量。ZENKUU 不收录任何订单簿，也不提供任何交易：本名录只标示活跃所在，并不提供入口。",
  "Où s’échange le marché au comptant": "现货市场在哪里成交",
  "Les places d’échange classées par note de confiance, avec le volume qu’elles déclarent sur 24 heures et la part qu’il représente dans ce classement. ZENKUU ne référence aucun carnet d’ordres et ne permet aucune transaction : ce registre situe l’activité, il n’y donne pas accès.": "交易平台按可信度评分排序，附其 24 小时申报成交量及在本榜单中的占比。ZENKUU 不收录任何订单簿，也不提供任何交易：本名录只标示活跃所在，并不提供入口。",
  "Tableau de bord": "面板",
  "Vos actifs suivis et vos préférences d’affichage. ZENKUU n’exécute aucun ordre et ne détient aucun fonds : il n’y a donc ici ni solde, ni portefeuille, ni performance — seulement ce que vous avez choisi de suivre.": "你关注的资产与显示偏好。ZENKUU 不执行任何委托，也不托管资金：因此这里没有余额、没有持仓、没有收益——只有你选择关注的内容。",

