  /* ── Interface : réglages, contrats, méthode ─────── */
  'Ce que ZENKUU ne fait pas.': 'ZENKUU 不做什么。',
  'Ce que ZENKUU n’est pas': 'ZENKUU 不是什么',
  'Ce que ZENKUU sait de vous tient en deux lignes : une adresse et un pseudonyme. Il n’y a ni mot de passe, ni profil, ni identité vérifiée.': 'ZENKUU 掌握的关于你的信息只有两行：一个地址和一个昵称。没有密码，没有档案，也没有实名验证。',
  'Ce que cet onglet examine': '本标签页考察的范围',
  'Ce que nous ne faisons pas': '我们不做什么',
  'Ce que nous ne reprenons pas de nos sources': '我们不采用数据源的哪些内容',
  'Ce que nous n’affichons pas': '我们不展示什么',
  'Ce que vous avez déjà suivi ou surveillé depuis ce navigateur rejoindra votre compte.': '你在此浏览器中已跟踪或监控的内容将并入你的账户。',
  'Ce qui s’est passé': '发生了什么',
  'Ce qui vient d’apparaître': '刚刚出现的',
  'Ce qu’on y trouvera': '你会在那里找到什么',
  'Ce seuil est déjà franchi : l’alerte partira au prochain relevé, dans quelques minutes.': '该阈值已被越过：提醒将在数分钟后的下一次读数时发出。',
  'Certaines lignes disparaissent quand la comparaison mêle plusieurs classes — volume, rang, offre. Ce n’est pas une donnée manquante mais une grandeur qui change de définition : le volume d’une place boursière se compte en titres échangés, celui d’un agrégateur crypto en monnaie. Les aligner donnerait un rapport sans signification.': '当比较跨越多个资产类别时，成交额、排名、供应量等行会消失。这不是数据缺失，而是同一名称下定义已变：证券交易所以成交股数计量成交，加密聚合平台以金额计量。强行并列只会得到毫无意义的比值。',
  'Ces réglages sont enregistrés dans ce navigateur, sur cet appareil.': '这些设置保存在本设备的此浏览器中。',
  'Ces sources se demandent par tranches et limitent les appels gratuits : le premier chargement peut prendre quelques secondes. Les suivants sont servis depuis le cache.': '这些数据源需分批请求且限制免费调用次数：首次加载可能需要几秒，之后从缓存读取。',
  'Ces trois réglages ne sont pas rattachés à votre compte : ils ne suivent donc pas d’un appareil à l’autre. Seule votre liste de suivi est synchronisée.': '这三项设置不与账户绑定，因此不会跨设备同步。只有你的关注列表会同步。',
  'Cette source se demande une entrée à la fois et limite fortement les appels gratuits : le premier chargement peut prendre plusieurs dizaines de secondes. Les suivants sont servis depuis le cache pendant une heure.': '该数据源只能逐条请求且严格限制免费调用：首次加载可能需要数十秒，之后一小时内从缓存读取。',
