  'Les alertes de prix préviennent par courriel. Tant que le service d’envoi n’est pas configuré sur cette instance, elles ne sont pas proposées — plutôt que d’être enregistrées sans jamais partir.': '价格提醒通过邮件通知。在本实例尚未配置发送服务前，我们不提供该功能——而不是保存下来却永远发不出去。',
