  'Paires cotées sur cette place': '该平台上线的交易对',
  'Palmarès du jour': '今日榜单',
  'Parcourir les cryptomonnaies': '浏览加密货币',
  'Parcourir par rubrique': '按栏目浏览',
  'Ouvrez la fiche d’un actif et utilisez le bouton « Suivre » pour l’ajouter ici.': '打开某个资产页，用「关注」按钮把它加到这里。',
  'Ouvrez la fiche d’un actif et utilisez le bouton « Suivre » pour l’ajouter ici. Aucun compte n’est nécessaire.': '打开某个资产页，用「关注」按钮把它加到这里。无需账户。',
  'Ouvrez la fiche d’un actif et utilisez « Créer une alerte » pour être prévenu par courriel au franchissement d’un seuil. Aucun compte n’est nécessaire.': '打开某个资产页，用「创建提醒」在越过阈值时收到邮件。无需账户。',
  'Le nombre d’adresses distinctes est plus difficile à gonfler que celui des transactions : combien de mains, et non combien de gestes.': '不同地址的数量比交易笔数更难灌水：看有多少只手，而不是有多少次动作。',
  'La liste de suivi est conservée en base, et c’est elle que cette page réunit. Vos préférences d’affichage, elles, restent enregistrées sur cet appareil.': '关注列表保存在数据库中，本页汇总的正是它。而你的显示偏好仍保存在本设备上。',
  'La note de confiance est un jugement publié par la source sur la qualité de la liquidité déclarée — pas une mesure, et pas un avis de ZENKUU. Les volumes sont ceux annoncés par les places elles-mêmes.': '信任评分是数据源就所申报流动性质量给出的判断——不是测量值，也不是 ZENKUU 的观点。成交量为各平台自行公布的数字。',
  'Les autres pools du même jeton de base, du plus profond au moins profond.': '同一基础代币的其他资金池，按深度从高到低。',
  'Les indicateurs affichés décrivent des données passées. Aucun n’est assorti d’un signal d’achat ou de vente.': '所示指标描述的是历史数据。没有任何一个附带买入或卖出信号。',
  'Les langues traduites changent l’interface ; les autres enregistrent votre préférence en attendant leur traduction. Le sélecteur signale lesquelles le sont.': '已翻译的语言会改变界面；其余语言只记录你的偏好，等待翻译完成。选择器中有标注。',
  'Les listes de suivi sont conservées en base. Tant qu’aucune n’est configurée sur cette instance, elles ne peuvent pas l’être.': '关注列表保存在数据库中。只要本实例尚未配置，就无法保存。',
  'Message repris dans le courriel — « sortir la moitié », « vérifier le volume »…': '会写进邮件的备注——「卖出一半」「查一下成交量」……',
  'Les cours sont convertis depuis leur devise de cotation au taux de référence BCE, dont la date est rappelée sous chaque montant. Une conversion n’est pas un cours coté.': '价格按欧洲央行参考汇率从计价货币换算而来，汇率日期标注在每个金额下方。换算值不是报价。',
  'Les cours sont relevés toutes les quinze minutes. Au franchissement du seuil, un courriel part sur l’adresse indiquée à la création. Une alerte ordinaire se désarme alors ; une alerte « à chaque fois » reste armée, avec au plus un envoi par jour.': '价格每十五分钟读取一次。越过阈值时，邮件发往创建时填写的地址。普通提醒随即解除；「每次都提醒」则保持启用，每天最多发送一次。',

