  'Plutôt que de remplir cette page de billets de circonstance, elle reste vide jusqu’au premier vrai article. Les contenus explicatifs du site sont, eux, bien réels.': '与其用应景短文把这页填满，不如让它空着，直到第一篇真正的文章。至于本站的说明性内容，那是实打实存在的。',
