  'Taux par période de financement — le plus souvent huit heures, jamais annualisé ici. Un taux positif signifie que les positions acheteuses paient les vendeuses.': '按每个资金费率周期计的费率——通常为八小时，此处不作年化。费率为正表示多头向空头支付。',
