  'Un ETF **européen n’y figure pas** — la sélection est américaine.': '**欧洲 ETF 不会出现在其中**——这份名单是美国的。',
  'Un narratif en tête explique souvent la présence d’une demi-douzaine de jetons dans les palmarès ci-dessus.': '某个主导叙事往往能解释上面榜单里为何同时出现半打代币。',
  'Un site de cotation s’arrête à 24 h ; sur la chaîne, cinq minutes comptent.': '行情站以 24 小时为限；在链上，五分钟就有分量。',
  'Une session dure soixante jours. « Tout fermer » révoque celles de tous vos appareils, y compris celui-ci — le geste à faire après avoir utilisé un poste partagé.': '会话有效期为六十天。「全部关闭」会撤销你所有设备上的会话，包括当前这台——用过公用电脑后应当这么做。',
