  'Nouvelles cotations': '新上市',
  'ZENKUU agrège des titres publiés par des éditeurs tiers et renvoie vers leurs articles. Aucun texte intégral n’est republié, et ZENKUU n’est l’auteur d’aucun de ces contenus.': 'ZENKUU 汇集第三方媒体发布的标题，并链接至其原文。本站不转载全文，这些内容亦非 ZENKUU 所著。',
  '**{n}** sur {total} cryptomonnaies retenus': '{total} 种加密货币中的 **{n}** 种',
  '**{n}** sur {total} actions retenus': '{total} 只股票中的 **{n}** 只',
