  'ZENKUU n’expose **aucune API publique** à ce jour. Les routes ci-dessous sont internes : elles servent les pages du site, ne sont pas versionnées et peuvent changer sans préavis. Elles sont documentées par transparence, pas comme un contrat.': '迄今为止，ZENKUU **不提供任何公开 API**。以下路由属内部使用：它们为站内页面服务，不做版本管理，且可能不经通知即变更。此处记录只为透明，并非一项承诺。',
