  /* ── Graphiques, aide et réglages — deuxième lot ─────────────────────────────────────────── */
  'Affichage': '布局',
  'Apparence': '外观',
  'Aucune source gratuite ne publie l’historique de dominance : nous l’enregistrons à chaque lecture des statistiques globales. La courbe apparaîtra dès que suffisamment de points auront été relevés.': '没有免费数据源发布市占率历史，因此我们在每次读取全球统计时自行记录。积累足够数据点后，曲线便会显示。',
  'Capitalisation de Bitcoin': '比特币市值',
  'Capitalisation du panier suivi': '追踪篮子的市值',
  'Capitalisation d’Ethereum': '以太坊市值',
  'Carte indisponible': '热力图不可用',
  'Choisir la devise': '选择货币',
  'Choisir la langue': '选择语言',
  'Collections indisponibles': '藏品不可用',
  'Compte': '账户',
  'Courbes longues indisponibles': '长周期曲线不可用',
  'Devise': '货币',
  'Découpage': '划分',
  'Efface le compte, la liste de suivi et les écrans enregistrés. Immédiat et sans période de grâce : conserver trente jours des données que personne ne réclame serait moins protecteur, pas plus.': '删除账户、关注列表和已保存的视图。立即生效，没有宽限期：把无人索取的数据保留三十天只会削弱保护，而非加强。',
  'La capitalisation des cryptomonnaies suivies s’élève aujourd’hui à {cap}, en variation de {change} sur vingt-quatre heures, pour un volume échangé de {volume}. Bitcoin en représente {btc}, Ethereum {eth}. Le site suit {count} cryptomonnaies.': '所追踪加密货币的总市值今日为 {cap}，二十四小时变动 {change}，成交额 {volume}。其中比特币占 {btc}，以太坊占 {eth}。本站共追踪 {count} 种加密货币。',
  'La dominance ci-dessus est la vraie : Bitcoin rapporté au marché entier, tel que la source le publie. Sa profondeur est celle de nos propres relevés, c’est-à-dire quelques heures. Pour voir la tendance sur douze mois, il faut accepter une mesure approchante — la part de Bitcoin dans un panier de neuf actifs, dont la composition est listée sous les courbes. Elle est tracée dans le cadre « Part de Bitcoin dans le panier », juste en dessous.': '上方的市占率是真实数值：按数据源公布的口径，比特币相对整个市场的占比。其深度取决于我们自己的记录，也就是数小时。若要观察十二个月的走势，就得接受一个近似指标——比特币在九种资产组成的篮子中的占比，篮子成分列于曲线下方。该指标绘制在紧接下方的「篮子中的比特币占比」图中。',
  'La somme de neuf grandes capitalisations, additionnées jour par jour — pas le marché entier.': '九个大市值逐日相加的总和，而非整个市场。',
  'La source ne publie pas la variation de Bitcoin sur trente jours pour le moment. L’indice compte les actifs qui font mieux que lui : sans cette valeur, il n’a pas de point de comparaison.': '数据源目前未公布比特币的三十日涨跌幅。该指数统计表现优于比特币的资产，缺少这一数值就失去了比较基准。',
  'Langue': '语言',
  'Le compte, la liste de suivi et les écrans enregistrés seront effacés immédiatement. Cette action est irréversible.': '账户、关注列表和已保存的视图将被立即删除。此操作无法撤销。',
  'Le panier est figé : il ne suit pas les entrées et sorties du classement. Sa courbe décrit ces neuf actifs, et rien d’autre.': '篮子是固定的：不会跟随排行榜的进出。其曲线只描述这九种资产，别无其他。',
  'Le volume échangé sur l’ensemble des places, tel que la source l’agrège.': '数据源汇总的全部交易场所成交量。',
  'Même relevé, même profondeur.': '同一次记录，同样的深度。',
  'Part de Bitcoin dans le panier': '篮子中的比特币占比',
