  'Comptage brut sur les {n} premières capitalisations, hors Bitcoin lui-même et hors stablecoins — dont la variation ne mesure rien d’autre que l’écart à leur ancrage. Ce n’est pas un signal d’achat ni de vente : voir [ce que ZENKUU ne fait pas](/aide/pas-de-conseil).': '对市值前 {n} 名的原始计数，剔除比特币本身与稳定币——后者的涨跌只反映相对锚定值的偏离。这并非买卖信号：参见[ZENKUU 不做的事](/aide/pas-de-conseil)。',

