  /* ── Fiche d’actif — explications et mentions ─────────────────────────────────────────── */
  'La pastille de couleur reprend le jugement de la source sur la crédibilité du volume annoncé — ce n’est pas un avis de ZENKUU. La profondeur ±2 % est le montant qu’il faudrait exécuter pour déplacer le cours de deux pour cent, à l’achat puis à la vente, en dollars.': '彩色圆点反映的是数据源本身对所报成交量可信度的判断，并非 ZENKUU 的意见。±2 % 深度指的是买入及卖出时，要让价格移动百分之二所需成交的美元金额。',
  'ZENKUU n’exécute aucun ordre et ne détient aucun fonds. Ces liens mènent à des plateformes tierces, citées sans recommandation.': 'ZENKUU 不执行任何委托，也不保管任何资金。这些链接指向第三方平台，列出但不构成推荐。',
  'Registre déclaratif : il recense ce que ces sociétés ont ANNONCÉ détenir, à la date de leur annonce. Ce n’est ni une mesure on-chain ni un état vérifié. Le coût total et la valeur du jour sont publiés en dollars ; leur écart est une plus ou moins-value latente, rien n’a été réalisé.': '这是一份申报登记：记录这些公司在其公告之日宣称持有的数量，既非链上实测，也非经审计的报表。取得成本与当日价值以美元公布，两者之差为浮动盈亏——并未实际卖出。',
  'Vote des visiteurs de la source, et non une mesure de marché : rien ne garantit qu’un vote corresponde à une position détenue.': '这是数据源访客的投票，而非市场测量：无法保证一张选票对应着实际持有的仓位。',
  'Opinions de bureaux d’analyse, pas une prévision. Le consensus penche structurellement à l’achat : les recommandations de vente y sont rares.': '这是各研究机构的观点，而非预测。共识在结构上偏向买入：其中卖出评级极为少见。',
  'Un jeton adossé à une action n’EST pas cette action&nbsp;: il en réplique le cours par un mécanisme propre à son émetteur, avec ses propres risques de contrepartie et de liquidité. Les montants sont publiés en dollars par la source.': '以股票为支撑的代币并不是该股票：它通过发行方特有的机制复制价格，并带有其自身的对手方风险与流动性风险。金额由数据源以美元公布。',
  'Dernière valeur reçue pour chaque journée. La variation est calculée d’une journée à la précédente au sein de cette série.': '每一天所接收到的最后一个数值。涨跌幅按本序列内前一日为基准计算。',
