  'résultat': '条结果',
  'À quelle fréquence les données sont-elles mises à jour ?': '数据多久更新一次？',
  'Toutes les trois minutes. La page est rendue une fois pour tous les visiteurs puis resservie depuis le cache jusqu’à expiration de ce délai — c’est ce qui permet de la servir sans épuiser le quota de la source. La date du dernier relevé est écrite sous le tableau, à côté du nom de la source.': '每三分钟一次。页面为所有访问者生成一次，随后在该时限内从缓存提供，这样才能在不耗尽数据源配额的情况下持续供数。最近一次取数的时间写在表格下方、数据源名称旁边。',
  'Combien d’actifs cette page recense-t-elle ?': '这个页面收录了多少种资产？',
  'Le compteur sous le tableau donne le nombre exact au moment où vous lisez, et il vient de la source — il n’est jamais écrit en dur. Le tableau en sert une tranche à la fois ; le sélecteur « Lignes » décide de sa taille, et la pagination parcourt le reste.': '表格下方的计数给出你阅读时的准确数量，它来自数据源，从不写死。表格每次只呈现其中一段；“行数”选择器决定这一段的大小，翻页则走完其余部分。',
  'Comment le classement est-il ordonné ?': '排行榜按什么顺序排列？',
  'Par capitalisation boursière décroissante par défaut, c’est-à-dire du plus grand au plus petit. Cliquer l’intitulé d’une colonne réordonne la liste sur cette colonne, et un second clic inverse le sens. Les valeurs absentes vont toujours en dernier, dans les deux sens : « pas de donnée » n’est pas « zéro ».': '默认按市值降序，也就是由大到小。点击列标题会按该列重新排序，再点一次则反转方向。缺失值在两个方向上都排在最后：“无数据”不等于“零”。',
  'Qu’est-ce que la capitalisation boursière, et pourquoi compte-t-elle ?': '什么是市值，它为什么重要？',
  'C’est le cours multiplié par l’offre en circulation — les deux dernières colonnes du tableau. Elle mesure ce que vaudrait l’ensemble des unités existantes au cours actuel, et sert de repère de taille plutôt que de valeur : une capitalisation élevée ne dit rien de la liquidité réelle, qui se lit sur le volume 24 h.': '它是价格乘以流通供应量，也就是表格最后两列。它衡量按当前价格计算所有既有单位值多少钱，是规模的参照而非价值的参照：市值高并不代表真实流动性，流动性要看 24 小时成交量。',
  'Quelle est la différence entre une pièce et un jeton ?': '币和代币有什么区别？',
  'Une pièce (coin) a sa propre chaîne — Bitcoin, Ether. Un jeton (token) est émis sur la chaîne d’une autre — la plupart des lignes de ce tableau. La distinction n’a pas de colonne ici parce que notre source ne la publie pas : l’inventer par déduction donnerait une classification approximative présentée comme un fait.': '币拥有自己的链，例如 Bitcoin、Ether。代币则发行在别人的链上，本表大多数行都属于这一类。这里没有为该区分设列，因为数据源并未公布：靠推断补上，等于把粗略的分类当作事实呈现。',
  'Puis-je chercher un actif précis ou filtrer la liste ?': '我可以搜索某个具体资产或筛选列表吗？',
  'Deux outils, deux portées, et la différence compte. Le champ « Filtrer » au-dessus du tableau ne porte que sur les lignes CHARGÉES, et le décompte le dit dès qu’il est actif. La loupe de l’en-tête du site, elle, interroge l’ensemble du catalogue. Les fourchettes de capitalisation, de volume et de variation filtrent également les lignes chargées.': '两种工具、两种范围，区别很重要。表格上方的“筛选”框只作用于已加载的行，一旦启用，计数会明确说明这一点。而站点顶部的放大镜查询的是整个目录。市值、成交量和涨跌幅区间同样只筛选已加载的行。',
  'Qu’est-ce qui distingue ZENKUU d’une autre plateforme de données ?': 'ZENKUU 与其他数据平台有何不同？',
