  'Ce que le site fait, ce qu’il ne fait pas, et les limites que nous écrivons plutôt que de les dissimuler.': '本站做什么、不做什么，以及我们宁可写下而不隐藏的边界。',
  'Nos limites, écrites': '写下来的边界',
  'La somme des stablecoins en circulation, toutes chaînes confondues.': '所有链上流通稳定币的总量。',
  'Le filtre ne s’applique qu’aux lignes chargées. Utilisez la recherche de l’en-tête pour chercher dans l’ensemble du catalogue.': '筛选只作用于已加载的行。若要检索整个目录，请使用页头的搜索。',
  'L’ensemble des cryptomonnaies du classement': '排行榜中的全部加密资产',
  'Les actions cotées suivies par le site': '本站追踪的上市股票',
  'Les principales paires de change': '主要货币对',
  'Rang, cours, variations, volume, capitalisation et courbe 7 jours': '排名、价格、涨跌、成交量、市值与 7 天走势',
  'Les cinq fenêtres de variation côte à côte — 1 h, 24 h, 7 j, 30 j, 1 an': '五个涨跌窗口并排 — 1 小时、24 小时、7 天、30 天、1 年',
  'Plus haut de tous les temps, sa date, et l’écart qui l’en sépare aujourd’hui': '历史最高价、创下的日期，以及今天与它的差距',
  'Variation positive sur 24 heures': '24 小时内上涨',
  'Variation négative sur 24 heures': '24 小时内下跌',
  'Les cryptomonnaies classées par capitalisation, avec leurs variations.': '按市值排序的加密资产及其涨跌。',
  'Les paires de change majeures, telles que la Banque centrale les publie.': '由央行公布的主要货币对。',
  'Les cryptomonnaies classées par capitalisation, triables et paginées. Lecture seule : aucun ordre ne part d’ici.': '按市值排序的加密资产，可排序、可翻页。只读：这里不会发出任何订单。',
  'Les actions suivies par Zenkuu, leur cours et leur variation. Lecture seule : aucun ordre ne part d’ici.': 'Zenkuu 追踪的股票及其价格与涨跌。只读：这里不会发出任何订单。',
  'Les fonds indiciels cotés suivis par Zenkuu, leur cours et leur variation. Lecture seule : aucun ordre ne part d’ici.': 'Zenkuu 追踪的上市指数基金及其价格与涨跌。只读：这里不会发出任何订单。',
  'Les grands indices boursiers et leur variation, dans la même grille que le reste du site.': '主要股票指数及其涨跌，采用与站内其他页面相同的表格。',
  'Les paires de devises majeures et leur variation. Les taux affichés sont indicatifs et ne valent pas cotation.': '主要货币对及其涨跌。所示汇率仅供参考，不构成报价。',
  'Les matières premières cotées — énergie, métaux, agricoles — et leur variation.': '上市的大宗商品 — 能源、金属、农产品 — 及其涨跌。',

  /* ── CHAÎNES RENDUES PAR UNE EXPRESSION — COMPLÉMENT — ajouté le 2026-08-31 ── */
  ' — non publié': ' — 未公布',
