  '2 septembre 2026': '2026年9月2日',
  '31 août 2026': '2026年8月31日',
  '30 août 2026': '2026年8月30日',
  'Fiches d’actif : la barre d’outils, le zoom et les surfaces': '资产页面：工具栏、缩放与表面',
  'Screener, heatmap et pages graphiques': '筛选器、热力图与图表页面',
  'Douze langues, sans exception': '十二种语言，无一例外',
  'La structure des pages, recalée sur la référence': '页面结构，按参照重新校准',
  'Le graphique se zoome à la molette, centré sur le curseur. Le geste pilote la bande de navigation plutôt que l’axe : la position reste montrée, et l’on revient en tirant les poignées.': '图表可用滚轮以光标为中心缩放。该操作驱动的是导航条而非坐标轴：位置始终可见，拖动手柄即可返回。',
  'La courbe passe au rouge quand la fenêtre affichée se termine plus bas qu’elle n’a commencé. Une hausse garde l’azur de la marque.': '当所显示区间的收尾低于起点时，曲线转为红色。上涨则保留品牌的蔚蓝色。',
  'Le menu « Comparer » reçoit un champ de recherche et la navigation aux flèches. Il filtre la liste chargée, et le dit — il n’interroge pas le serveur.': '“比较”菜单新增搜索框与方向键导航。它只筛选已加载的列表，并明确说明——不会请求服务器。',
  'Les réglages du graphique passent en interrupteurs sous une roue dentée, avec leurs sections titrées.': '图表设置改为齿轮图标下的开关，并按标题分区。',
  'Le graphique TradingView suit désormais le thème RÉSOLU du site. Il restait en clair pour tout lecteur n’ayant jamais touché au réglage, le mode « système » étant la valeur par défaut.': 'TradingView 图表现在跟随站点的「已解析」主题。由于默认值是「跟随系统」，从未改过该设置的读者此前始终看到浅色。',
  'Sous TradingView, « Capitalisation » charge le symbole que la plateforme publie pour elle, et se grise là où il n’en existe aucun.': '在 TradingView 模式下，“市值”会加载该平台自行发布的代码；若无对应代码则置灰。',
  'Une page qui glissait de quatorze pixels à l’ouverture de tout menu ne bouge plus : deux compensations de barre de défilement se contredisaient.': '此前每次打开菜单都会偏移十四像素的页面不再移动：两处滚动条补偿相互抵触。',
  '/categories/ecosystemes rejoint /categories comme une vue, avec redirection. Les deux pages rendaient le même composant sur la même requête.': '/categories/ecosystemes 并入 /categories 成为一个视图，并设置跳转。两个页面此前在同一请求上渲染同一组件。',
  'Le screener reçoit des filtres à fourchette, des écrans prédéfinis et un panneau de catégories.': '筛选器新增区间筛选、预设视图与分类面板。',
  'La heatmap adopte une rampe continue plutôt que des paliers, et ses libellés repassent le seuil de contraste.': '热力图改用连续色阶而非分档，其标签重新达到对比度阈值。',
  'Les pages graphiques prennent la structure de leur référence : bandes de repères, légende à droite du tracé, tracés en barres.': '图表页面采用参照的结构：指标条带、位于绘图区右侧的图例、柱状绘制。',
  'Une barre d’onglets en pied d’écran sur téléphone, à portée de pouce.': '手机端在屏幕底部设置标签栏，位于拇指可及处。',
  'Les pages /blog et /apprendre sont retirées du site, sans redirection ni vestige.': '/blog 与 /apprendre 页面已从站点移除，不设跳转，不留残余。',
  'Tous les textes de l’interface passent par la table de phrases, y compris ceux qu’une balise coupait en deux et ceux qui vivaient dans un attribut ou un ternaire.': '界面上的所有文本均经由短语表，包括被标签截成两半的，以及藏在属性或三元表达式中的。',
  'Le glossaire et les deux foires aux questions sont traduits dans les douze langues.': '术语表与两处常见问题已译成全部十二种语言。',
  'Deux relevés indépendants de textes non traduits tombent à zéro.': '两次独立统计的未翻译文本数量均降为零。',
  'L’accueil, la navigation et les fiches d’actif reprennent la disposition de la référence, mesurée au navigateur page par page.': '首页、导航与资产页采用参照的版式，逐页在浏览器中实测得出。',
  'Le panneau d’actualités revient sur les fiches : il avait été retiré sur une mesure fausse.': '资讯面板回到资产页：此前是依据一次错误的测量被移除的。',
  'Les contrastes de texte sur fond coloré et les états sélectionnés reviennent à la mesure.': '彩色背景上的文字对比度与选中态回到实测值。',
